From 67ef497f4d3ec3066c829c9101995065cfbdb0ff Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:14:28 +0100
Subject: [PATCH] applet: stop volume meters while a window covers the desktop
 widget

A widget on the desktop is always visible as far as Qt knows, so its
level meters kept recording every device even when a window hid it. Now
they pause while a window covers the whole widget, like in the tray.

BUG: 441555
---
 applet/VolumeSlider.qml |  2 +-
 applet/main.qml         | 79 +++++++++++++++++++++++++++++++++++++++++
 2 files changed, 80 insertions(+), 1 deletion(-)

diff --git a/applet/VolumeSlider.qml b/applet/VolumeSlider.qml
index 5f365ccb..38e7227f 100644
--- a/applet/VolumeSlider.qml
+++ b/applet/VolumeSlider.qml
@@ -35,7 +35,7 @@ PC3.Slider {

     VolumeMonitor {
         id: meter
-        target: control.visible && control.showVolumeIndicator ? control.volumeObject : null
+        target: control.visible && control.showVolumeIndicator && !main.coveredByWindow ? control.volumeObject : null
     }

     Behavior on volume {
diff --git a/applet/main.qml b/applet/main.qml
index 1e44cded..54fe84b4 100644
--- a/applet/main.qml
+++ b/applet/main.qml
@@ -17,6 +17,8 @@ import org.kde.plasma.plasmoid

 import org.kde.kcmutils as KCMUtils
 import org.kde.config as KConfig
+import org.kde.kwindowsystem
+import org.kde.taskmanager as TaskManager

 import org.kde.plasma.private.volume

@@ -46,6 +48,83 @@ PlasmoidItem {
         || Plasmoid.location === PlasmaCore.Types.LeftEdge)
     readonly property bool compactInPanel: inPanel && !!compactRepresentationItem?.visible

+    // A widget on the desktop is always visible as far as Qt knows, so stop the
+    // volume meters ourselves while a window covers it completely.
+    readonly property bool coveredByWindow: coveredWatcher.item?.covered ?? false
+
+    Loader {
+        id: coveredWatcher
+        active: !main.inPanel
+
+        sourceComponent: Item {
+            property bool covered: false
+
+            function update(): void {
+                if (KWindowSystem.showingDesktop || main.width <= 0 || main.height <= 0) {
+                    covered = false;
+                    return;
+                }
+                const screen = Plasmoid.containment.screenGeometry;
+                const pos = main.mapToItem(null, 0, 0);
+                const x = screen.x + pos.x;
+                const y = screen.y + pos.y;
+                for (let i = 0; i < windowsModel.count; ++i) {
+                    const geometry = windowsModel.data(windowsModel.index(i, 0), TaskManager.AbstractTasksModel.Geometry);
+                    if (geometry.x <= x && geometry.y <= y
+                        && geometry.x + geometry.width >= x + main.width
+                        && geometry.y + geometry.height >= y + main.height) {
+                        covered = true;
+                        return;
+                    }
+                }
+                covered = false;
+            }
+
+            TaskManager.TasksModel {
+                id: windowsModel
+                filterByCurrentVirtualDesktop: true
+                filterByActivity: true
+                filterByScreen: true
+                filterHidden: true
+                filterMinimized: true
+                screenGeometry: Plasmoid.containment.screenGeometry
+                activity: activityInfo.currentActivity
+                groupMode: TaskManager.TasksModel.GroupDisabled
+
+                onCountChanged: updateTimer.restart()
+                onDataChanged: updateTimer.restart()
+                onModelReset: updateTimer.restart()
+            }
+
+            TaskManager.ActivityInfo {
+                id: activityInfo
+            }
+
+            Connections {
+                target: KWindowSystem
+                function onShowingDesktopChanged() {
+                    updateTimer.restart();
+                }
+            }
+
+            Connections {
+                target: main
+                function onXChanged() { updateTimer.restart(); }
+                function onYChanged() { updateTimer.restart(); }
+                function onWidthChanged() { updateTimer.restart(); }
+                function onHeightChanged() { updateTimer.restart(); }
+            }
+
+            Timer {
+                id: updateTimer
+                interval: 0
+                onTriggered: parent.update()
+            }
+
+            Component.onCompleted: update()
+        }
+    }
+
     // DEFAULT_SINK_NAME in module-always-sink.c
     readonly property string dummyOutputName: "auto_null"
     readonly property bool appletContextReady: Context.state === Context.State.Ready
-- 
